    { "id": "P01", "name": "庄公" },
    { "id": "P02", "name": "姜氏" },
    { "id": "P03", "name": "共叔段" },
    { "id": "P04", "name": "祭仲" },
    { "id": "P05", "name": "公子吕" },
    { "id": "P06", "name": "颍考叔" }
  ],
  "locations": [
    { "id": "L01", "name": "郑国朝堂" },
    { "id": "L02", "name": "京邑、鄢、郑都城门" },
    { "id": "L03", "name": "城颍" },
    { "id": "L04", "name": "隧道" }
  ],
  "scenes": [
    {
      "sceneId": "L01",
      "characters": ["P01", "P02", "P04"],
      "flow": [
        { "action": "姜氏展开郑国地图，手指京邑。" },
        { "speaker": "P02", "line": "庄公寤生，惊我，我恶之。", "mode": "spoken" },
        { "speaker": "P02", "line": "我爱共叔段，欲立之。", "mode": "spoken" },
        { "speaker": "P02", "line": "我欲立段，未获许可。", "mode": "spoken" },
        { "speaker": "P02", "line": "庄公即位，我为段请制。", "mode": "spoken" },
        { "speaker": "P01", "line": "制，岩邑也。佗邑唯命。", "mode": "spoken" },
        { "speaker": "P02", "line": "请京，使段居之。", "mode": "spoken" },
        { "speaker": "P04", "line": "都城过百雉，非制也，君将不堪。", "mode": "spoken" },
        { "speaker": "P04", "line": "姜氏何厌之有？不如早为之所。", "mode": "spoken" },
        { "speaker": "P04", "line": "蔓草犹不可除，况君之宠弟乎？", "mode": "spoken" },
        { "speaker": "P01", "line": "多行不义，必自毙，子姑待之。", "mode": "spoken" },
        { "action": "祭仲把地图卷起。" }
      ]
    },
    {
      "sceneId": "L01",
      "characters": ["P01", "P05"],
      "flow": [
        { "action": "公子吕拱手奏事。" },
        { "speaker": "P05", "line": "大叔命西鄙、北鄙贰于己。", "mode": "spoken" },
        { "speaker": "P05", "line": "国不堪贰，请除之，无生民心。", "mode": "spoken" },
        { "speaker": "P05", "line": "欲与大叔，臣请事之；若弗与，则请除之。", "mode": "spoken" },
        { "speaker": "P05", "line": "可矣，厚将得众。", "mode": "spoken" },
        { "speaker": "P01", "line": "不义，不昵，厚将崩。", "mode": "spoken" },
        { "action": "公子吕退到阶下。" }
      ]
    },
    {
      "sceneId": "L02",
      "characters": ["P01", "P02", "P03", "P05"],
      "flow": [
        { "action": "共叔段检查甲兵。" },
        { "speaker": "P02", "line": "门开了，段公子。", "mode": "spoken" },
        { "speaker": "P01", "line": "可矣。子封，率车伐京。", "mode": "spoken" },
        { "action": "公子吕挥旗。" },
        { "speaker": "P03", "line": "京叛大叔段，我入鄢。", "mode": "spoken" },
        { "action": "共叔段出奔共。" }
      ]
    },
    {
      "sceneId": "L03",
      "characters": ["P01", "P02", "P06"],
      "flow": [
        { "action": "庄公把姜氏安置在城颍。" },
        { "speaker": "P01", "line": "不及黄泉，无相见也。", "mode": "spoken" },
        { "action": "颍考叔献上一盘肉食。" },
        { "speaker": "P06", "line": "小人有母，请以遗之。", "mode": "spoken" },
        { "speaker": "P01", "line": "尔有母遗，我独无！", "mode": "spoken" },
        { "speaker": "P06", "line": "若阙地及泉，隧而相见。", "mode": "spoken" }
      ]
    },
    {
      "sceneId": "L04",
      "characters": ["P01", "P02"],
      "flow": [
        { "action": "庄公进入隧道。" },
        { "speaker": "P01", "line": "大隧之中，其乐也融融。", "mode": "spoken" },
        { "action": "姜氏走出隧道。" },
        { "speaker": "P02", "line": "大隧之外，其乐也泄泄。", "mode": "spoken" },
        { "action": "庄公与姜氏并肩而立。" }
      ]
    }
  ]
}

